import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { getContractAddress, keccak256, type Address, type Hex } from "viem";
import {
  channelIdOf,
  closeChannelDigest,
  initConfigDigest,
  mandateChangeDigest,
  openChannelDigest,
  revokeSessionDigest,
  vaultSalt,
  voucherDigest,
  worldApprovalDigest,
} from "../src/eip712.js";
import { Action, decodeOps, encode, encodeOps } from "../src/actions.js";

// Generated by contracts/test/Eip712Vectors.t.sol from the real contracts.
const v = JSON.parse(
  readFileSync(new URL("../../../contracts/test/vectors/eip712.json", import.meta.url), "utf8"),
) as Record<string, string | number>;
const chainId = Number(v.chainId);
const t0 = BigInt(v.t0);
const vault = v.vault as Address;
const factory = v.factory as Address;
const merchant = v.merchant as Address;
const session = v.session as Address;
const subject = v.subject as Hex;

describe("EIP-712 digests match the contracts (shared vectors)", () => {
  it("OpenChannel", () => {
    expect(
      openChannelDigest(chainId, vault, { vault, merchant, amount: 12_345_678n, expiry: t0 + 3600n, sessionNonce: 42n }),
    ).toBe(v.openDigest);
  });

  it("channelId", () => {
    expect(channelIdOf(vault, session, merchant, 42n)).toBe(v.channelId);
  });

  it("Voucher", () => {
    expect(voucherDigest(chainId, vault, { channelId: v.channelId as Hex, cumulativeAmount: 987_654n })).toBe(
      v.voucherDigest,
    );
  });

  it("MandateChange (single op) and its data encoding", () => {
    const op = encode.setSessionLimits(session, t0 + 86_400n, 80_000_000n);
    expect(op.data).toBe(v.changeData);
    expect(mandateChangeDigest(chainId, vault, { action: op.action, data: op.data, nonce: 0n, deadline: t0 + 600n })).toBe(
      v.changeDigest,
    );
  });

  it("MandateChange (BATCH) and Op[] encoding round-trip", () => {
    const ops = [encode.setMerchant(merchant, 100_000_000n, 20_000_000n), encode.addSession(session, t0 + 86_400n, 50_000_000n)];
    const data = encodeOps(ops);
    expect(data).toBe(v.initialMandate);
    expect(decodeOps(data)).toEqual(ops);
    expect(mandateChangeDigest(chainId, vault, { action: Action.BATCH, data, nonce: 7n, deadline: t0 + 900n })).toBe(
      v.batchChangeDigest,
    );
  });

  it("WorldApproval (vault domain)", () => {
    expect(
      worldApprovalDigest(chainId, vault, {
        vault,
        changeHash: v.changeDigest as Hex,
        nonce: 0n,
        worldSubjectHash: subject,
        authTime: t0,
        deadline: t0 + 600n,
      }),
    ).toBe(v.worldApprovalDigest);
  });

  it("InitConfig + creation WorldApproval (factory domain)", () => {
    const init = initConfigDigest(chainId, factory, {
      pqPubKeyHash: v.pqPubKeyHash as Hex,
      worldSubjectHash: subject,
      verifier: v.verifier as Address,
      initialMandate: v.initialMandate as Hex,
    });
    expect(init).toBe(v.initDigest);
    expect(
      worldApprovalDigest(chainId, factory, {
        vault,
        changeHash: init,
        nonce: 0n,
        worldSubjectHash: subject,
        authTime: t0,
        deadline: t0 + 600n,
      }),
    ).toBe(v.initWorldApprovalDigest);
  });

  it("CloseChannel and RevokeSession", () => {
    expect(closeChannelDigest(chainId, vault, { channelId: v.channelId as Hex, finalAmount: 555n })).toBe(v.closeDigest);
    expect(revokeSessionDigest(chainId, vault, session)).toBe(v.revokeDigest);
  });

  it("vault salt", () => {
    expect(vaultSalt(v.pqPubKeyHash as Hex, subject)).toBe(v.salt);
  });

  it("predicted vault address = EIP-1167 CREATE2 clone of the implementation", () => {
    // implementation = first contract created by the factory (nonce 1 for a contract deployer)
    const impl = getContractAddress({ from: factory, nonce: 1n });
    const initCode = `0x3d602d80600a3d3981f3363d3d373d3d3d363d73${impl.slice(2).toLowerCase()}5af43d82803e903d91602b57fd5bf3` as Hex;
    const predicted = getContractAddress({ opcode: "CREATE2", from: factory, salt: v.salt as Hex, bytecodeHash: keccak256(initCode) });
    // deployCodeTo etches the factory without a nonce bump, so the implementation may sit at nonce 0 instead
    const impl0 = getContractAddress({ from: factory, nonce: 0n });
    const initCode0 = `0x3d602d80600a3d3981f3363d3d373d3d3d363d73${impl0.slice(2).toLowerCase()}5af43d82803e903d91602b57fd5bf3` as Hex;
    const predicted0 = getContractAddress({ opcode: "CREATE2", from: factory, salt: v.salt as Hex, bytecodeHash: keccak256(initCode0) });
    expect([predicted.toLowerCase(), predicted0.toLowerCase()]).toContain(vault.toLowerCase());
  });
});
